        adj.setdefault(b, []).append(a)

    from collections import deque

    # Generic BFS returning distance map from start
    def bfs(start):
        dist = {start: 0}
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj.get(u, []):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    # Case: source == target -> need a positive‑length round trip
    if source == target:
        dist = bfs(source)
        best = float('inf')
        for a, b in edges:
            if a in dist and b in dist:
                cand = dist[a] + dist[b] + 1   # go source→a, edge a‑b, then b→source
                if cand < best:
                    best = cand
        return int(best) if best != float('inf') else -1
    else:
        # Normal shortest‑path query
        dist = bfs(source)
        return dist.get(target, -1)
